export const isRecorder=p=>p?.type==='recorder'&&p.recorderProfile?.reviewed===true;
export function recorderFactsHTML(p,esc){if(!isRecorder(p))return '';const a=p.recorderProfile;return `<section class="frame-facts recorder-facts"><h4>Handheld recording reference</h4><p>${esc(a.recording)}</p><p>${esc(p.sizeBasis)}</p><p>${esc(a.connections)} ${esc(a.power)}</p><p>${esc(a.media)}</p><p>${esc(p.sourceOfferNote)}</p><a href="${esc(a.manufacturerSource)}" target="_blank" rel="noopener noreferrer">Manufacturer facts ↗</a><p>Photograph: Luisalvaz · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a> · orientation normalized, resized and encoded as WebP. Hands and surroundings in the photograph are not included.</p></section>`;}
export function recorderNotebookHTML(st,esc,choice='stereo'){
 const multi=choice==='multi',p=st.products.find(isRecorder);if(!p)return '';
 return `<div class="modal-body recorder-notebook"><span class="eyebrow">ORIGINAL RECORDING STUDIO · FREE COMPARISON</span><h3>What would you like to capture?</h3><p>Compare microphone layouts before inspecting the virtual H1n. Both source models are discontinued; this guide makes no claim of real availability.</p><div class="recorder-choices" role="group" aria-label="Recording scenario"><button class="button secondary" data-action="recorder-scenario" data-id="stereo" aria-pressed="${!multi}">Stereo interview</button><button class="button secondary" data-action="recorder-scenario" data-id="multi" aria-pressed="${multi}">Multi-input rehearsal</button></div><section class="recording-scenario" role="status"><h3>${multi?'More inputs, separate sources.':'Two microphones, one stereo scene.'}</h3><p>${multi?'The H4n Pro’s 4CH mode can combine its built-in X/Y microphones with two external inputs. Its two XLR/TRS combination sockets accept separate sources. Cables and microphones are separate equipment.':'The H1n has a fixed 90° X/Y pair for two-channel stereo recording. Compare that simple built-in layout with the H4n Pro’s adjustable 90°/120° pair.'}</p><div class="recording-meter" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p class="hint">Illustrative game meter only. No sound-quality comparison, audio playback or microphone recording.</p></section><div class="recording-reference-grid"><article><h4>H1n · virtual shop reference</h4><p>50 × 137.5 × 32 mm (W × D × H). Two AAA batteries. microSD/microSDHC up to 32 GB.</p><button class="button secondary wide" data-action="detail" data-id="${esc(p.id)}">Inspect the H1n & source</button></article><article><h4>H4n Pro · specifications only</h4><p>73 × 157.2 × 37 mm (W × D × H). Two AA batteries. Stereo, 4CH and MTR modes. Not a product sold in this game.</p><a href="https://zoomcorp.com/en/us/handheld-recorders/handheld-recorders/h4n-pro/" target="_blank" rel="noopener noreferrer">Manufacturer reference ↗</a></article></div><p class="hint">D is the manufacturer’s long body axis, not thickness. Opening this guide is free, pauses game time, and reserves no stock.</p><button class="button secondary" data-action="collection-open">Back to the collection desk</button></div>`;
}
const ease=t=>{const x=Math.max(0,Math.min(1,t));return x*x*x*(x*(x*6-15)+10);};
export function recorderHold(profile,time,reduced=false,rest){
 const t=Number.isFinite(time)?Math.max(0,time):0,reach=reduced?1:ease(t/.8)*(1-ease((t-3.5)/.9)),turn=reduced?0:t<1?0:t<1.9?.3*ease((t-1)/.9):t<2.4?.3:t<3.3?.3*(1-ease((t-2.4)/.9)):0;
 const k=.15*.4,width=profile.widthMM*k,length=profile.lengthMM*k,baseY=29,z=11,co=Math.cos(turn),si=Math.sin(turn),grips=[{x:-width/2,y:length*.22},{x:width/2,y:length*.48}];
 const hands=grips.map((h,i)=>{const a=rest?.[i]||{x:(i?1:-1)*10,y:22,z:1.5},b={x:h.x*co,y:baseY+h.y,z:z-h.x*si};return {x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};});
 return {reach,turn,hands,baseY:(hands[0].y+hands[1].y)/2-length*.35,z:(hands[0].z+hands[1].z)/2,visible:reduced||reach>.02};
}
